mapper.insert:
		INSERT INTO PRJ_PRJCT_COMP_ORG_INFO_TBL (
			COMP_ORG_SEQ
		  , 	PRJCT_ORG_CD
  	 	  , PRJCT_ORG_LVL
  	 	  , 	PRJCT_ORG_ORD
  	 	  , USE_YN
  	 	  , PRJCT_ORG_NM
  	 	  , PRNT_PRJCT_ORG_SEQ
  	 	  , PRJCT_ORG_DESC
  	 	  , RGST_DT
  	 	  , RGST_SEQ
  	 	  , RGST_NM
		)
		VALUES (
			#{compOrgSeq, jdbcType=NUMERIC}
		  , #{prjctOrgCd, jdbcType=VARCHAR}
		  , 	#{prjctOrgLvl, jdbcType=NUMERIC}
		  , (
				CASE
					WHEN ((#{prjctOrgOrd, jdbcType=NUMERIC} IS NULL) OR (#{prjctOrgOrd, jdbcType=NUMERIC} = 0)) THEN (
						SELECT 	(MAX(COMP_ORG.PRJCT_ORG_ORD)+ 1) 	AS MAX_PRJCT_ORG_ORD
						FROM 	PRJ_PRJCT_COMP_ORG_INFO_TBL	 COMP_ORG
						WHERE 	1 	= 	1
						AND 		COMP_ORG.DELT_YN 						=	'N'
						AND 		COMP_ORG.COMP_ORG_SEQ 			= 	#{compOrgSeq, jdbcType=NUMERIC}
						AND 		COMP_ORG.PRNT_PRJCT_ORG_SEQ 	= 	#{prntPrjctOrgSeq, jdbcType=NUMERIC}
					)
					ELSE   #{prjctOrgOrd, jdbcType=NUMERIC}
				END
			)
		  , (
				CASE
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
					ELSE  #{useYn, jdbcType=VARCHAR}
				END
		    )
		  , #{prjctOrgNm, jdbcType=VARCHAR}
		  , #{prntPrjctOrgSeq, jdbcType=NUMERIC}
		  , #{prjctOrgDesc, jdbcType=VARCHAR}
		  , CURRENT_TIMESTAMP(3)
		  , #{rgstSeq, jdbcType=NUMERIC}
		  , #{rgstNm, jdbcType=VARCHAR}
		)

mapper.update:
UPDATE PRJ_PRJCT_COMP_ORG_INFO_TBL
SET 		PRJCT_ORG_LVL 				= (
				CASE
					WHEN (#{prjctOrgLvl, jdbcType=NUMERIC} IS NULL OR #{prjctOrgLvl, jdbcType=NUMERIC} = 0) THEN PRJCT_ORG_LVL
					ELSE   #{prjctOrgLvl, jdbcType=NUMERIC}
				END
		   )
		  , PRJCT_ORG_ORD 			= (
				CASE
					WHEN (#{prjctOrgOrd, jdbcType=NUMERIC} IS NULL OR #{prjctOrgOrd, jdbcType=NUMERIC} = 0) THEN PRJCT_ORG_ORD
					ELSE   #{prjctOrgOrd, jdbcType=NUMERIC}
				END
		   )
		  , USE_YN 							= (
				CASE
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN
					ELSE   #{useYn, jdbcType=VARCHAR}
				END
		   )
		  , PRJCT_ORG_NM 				= (
				CASE
					WHEN (#{prjctOrgNm, jdbcType=VARCHAR} IS NULL OR #{prjctOrgNm, jdbcType=VARCHAR} = '') THEN PRJCT_ORG_NM
					ELSE   #{prjctOrgNm, jdbcType=VARCHAR}
				END
		   )
		  , PRNT_PRJCT_ORG_SEQ 	= (
				CASE
					WHEN (#{prntPrjctOrgSeq, jdbcType=NUMERIC} IS NULL OR #{prntPrjctOrgSeq, jdbcType=NUMERIC} = 0) THEN PRNT_PRJCT_ORG_SEQ
					ELSE  #{prntPrjctOrgSeq, jdbcType=NUMERIC}
				END
		   )
		  , PRJCT_ORG_DESC 			= (
				CASE
					WHEN (#{prjctOrgDesc, jdbcType=VARCHAR} IS NULL OR #{prjctOrgDesc, jdbcType=VARCHAR} = '') THEN PRJCT_ORG_DESC
					ELSE   #{prjctOrgDesc, jdbcType=VARCHAR}
				END
		   )
		  , UPDT_DT = CURRENT_TIMESTAMP(3)
		  , UPDT_SEQ = #{updtSeq, jdbcType=NUMERIC}
		  , UPDT_NM = #{updtNm, jdbcType=VARCHAR}
WHERE 	1 	= 	1
AND 		DELT_YN  = 'N'
AND 		COMP_ORG_SEQ =	#{compOrgSeq, jdbcType=NUMERIC}
AND 		(((#{prjctOrgSeq, jdbcType=NUMERIC} IS NULL) OR (#{prjctOrgSeq, jdbcType=NUMERIC} = 0)) OR (PRJCT_ORG_SEQ  =  #{prjctOrgSeq, jdbcType=NUMERIC}))
AND 		(((#{prjctOrgCd, jdbcType=VARCHAR} IS NULL) OR (#{prjctOrgCd, jdbcType=VARCHAR} = '')) OR (PRJCT_ORG_CD  =  #{prjctOrgCd, jdbcType=VARCHAR}))

mapper.delete:
UPDATE 	PRJ_PRJCT_COMP_ORG_INFO_TBL
SET 		USE_YN 		= 	'N'
		  , DELT_YN 	=	'Y'
		  , DELT_DT 	= 	CURRENT_TIMESTAMP(3)
		  , DELT_SEQ 	=	#{deltSeq, jdbcType=NUMERIC}
		  , DELT_NM 	= 	#{deltNm, jdbcType=VARCHAR}
WHERE 	1 	= 	1
AND 		COMP_ORG_SEQ 	=	#{compOrgSeq, jdbcType=NUMERIC}
AND 		PRJCT_ORG_SEQ 		= 	#{prjctOrgSeq, jdbcType=NUMERIC}

UPDATE PRJ_PRJCT_WRKR_INFO_TBL
SET 		USE_YN 		= 	'N'
		  , DELT_YN 	=	'Y'
		  , DELT_DT 	= 	CURRENT_TIMESTAMP(3)
		  , DELT_SEQ 	=	#{deltSeq, jdbcType=NUMERIC}
		  , DELT_NM 	= 	#{deltNm, jdbcType=VARCHAR}
WHERE 	1 	= 	1
AND 		COMP_ORG_SEQ 	=	#{compOrgSeq, jdbcType=NUMERIC}
AND 		PRJCT_ORG_SEQ 		= 	#{prjctOrgSeq, jdbcType=NUMERIC}

