SELECT 	(
				CASE
					WHEN (COUNT(PRJCT_ORG_CD)  >  0) THEN true
					ELSE   false 
				END
			) 	AS DUP_FLAG
FROM 	PRJ_PRJCT_COMP_ORG_INFO_TBL
WHERE 	1 	= 	1
AND 		COMP_ORG_SEQ 	=	#{compOrgSeq, jdbcType=NUMERIC}
AND 		PRJCT_ORG_CD 		= 	#{prjctOrgCd, jdbcType=VARCHAR}
